section.code:
add_object("lmdb", "Person", { givenName: "Ada",   sn: "Lovelace", dept: "ENG",  age: 36 }, "ada");
add_object("lmdb", "Person", { givenName: "Alan",  sn: "Turing",   dept: "MATH", age: 41 }, "alan");
add_object("lmdb", "Person", { givenName: "Grace", sn: "Hopper",   dept: "ENG",  age: 85 }, "grace");

index_create("lmdb", "dept", undefined, ["Person"], undefined, undefined, false);

retrieve_objects("lmdb", "Person", {
    filter: { op: "eq", property: "dept", value: "ENG" }
});

// The same query as a URL encoded RQL string, the form REST requests use:
retrieve_objects("lmdb", "Person", { urlEncodedRQLString: "dept=ENG" });

index_create("lmdb", "fullName",
    "return current::object.givenName + ' ' + current::object.sn;",
    ["Person"], undefined, undefined, false);

retrieve_objects("lmdb", "Person", {
    filter: { op: "eq", property: "fullName", value: "Ada Lovelace" }
});

index_create("lmdb", "seniorAge",
    "current::object.age",
    ["Person"],
    "return (current::object.age ?? 0) >= 40;",
    ["integer"], false);

// Alan and Grace; Ada is not indexed under seniorAge.
retrieve_objects("lmdb", "Person", { urlEncodedRQLString: "seniorAge=ge=40" });
